    fn flash_floor_and_ceil_across_boundaries() {
        let s = add_u64_with_carry(0u64, u64::MAX - 500u64);
        assert_eq!(ceil_div_flash_u64(s), 3_689_348_814_741_911u64);
        assert_eq!(floor_div_flash_u64(s), 3_689_348_814_741_910u64);

